const c = new Circle(1), r = new Rectangle(2, 3);
if (Math.abs(c.area() - Math.PI) > 1e-9) throw new Error("circle area");
if (r.area() !== 6) throw new Error("rectangle area");
if (c.describe() !== "circle: 3.14") throw new Error("describe got " + c.describe());
if (r.describe() !== "rectangle: 6.00") throw new Error("describe got " + r.describe());
if (!(c instanceof Shape)) throw new Error("Circle must extend Shape");

let threw = false;
try { new Shape(); } catch (e) { threw = true; }
if (!threw) throw new Error("new Shape() must throw");
const a = new Rectangle(1, 1), b = new Circle(2), c = new Rectangle(3, 2);
if (!(a.compareTo(b) < 0) || !(b.compareTo(a) > 0) || a.compareTo(new Rectangle(1, 1)) !== 0) throw new Error("compareTo");
if (largest([a, b, c]) !== b) throw new Error("largest should be the circle of radius 2");
if (Math.abs(totalArea([a, b, c]) - (1 + 4 * Math.PI + 6)) > 1e-9) throw new Error("totalArea");
